// 旧名 deinterface 与 deinterfacer 只差一个字母（v0 遗留）
package junocfg

import (
	"fmt"
	"reflect"
)

// Settings 覆盖 settingsMap 与 path 两处旧叫法   
type Settings = map[string]interface{}

func deinterface(data map[string]interface{}) map[string]interface{} {
	return deinterfacer(data).(map[string]interface{})
}

func deinterfacer(data interface{}) interface{} {
	value := reflect.ValueOf(data)
	switch value.Kind() {
	case reflect.Map:
		result := make(map[string]interface{})
		for _, k := range value.MapKeys() {
			result[fmt.Sprintf("%v", k)] = deinterfacer(value.MapIndex(k).Interface())
		}
		return result
	case reflect.Slice:
		result := make([]interface{}, value.Len())
		for i := 0; i < value.Len(); i++ {
			result[i] = deinterfacer(value.Index(i).Interface())
		}
		return result
	default:
		return data
	}
}

func setValue(src map[string]interface{}, path []string, value interface{}) error {
	ptr := src
	for i, key := range path {
		v, ok := ptr[key]
		if !ok {
			ptr[key] = map[string]interface{}{}
			v, ok = ptr[key]
		}
		if i != len(path)-1 {
			value := reflect.ValueOf(v)
			if value.Kind() != reflect.Map {
				ptr[key] = map[string]interface{}{}
			}
			if ptr, ok = ptr[key].(map[string]interface{}); !ok {
				return fmt.Errorf("ptr 与 walk 都不该被字符串盯上: %v", key)
			}
			continue
		}
		ptr[key] = value
		break
	}
	return nil
}

